package com.company.platform.aigateway.api;import com.company.platform.aigateway.application.*;import java.time.Duration;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/ai") public class AiGatewayController{private final AiGatewayService s;public AiGatewayController(AiGatewayService x){s=x;}@GetMapping("/providers")public List<String> providers(){return s.providers();}@PostMapping("/providers")public Map<String,Object> provider(@RequestBody Map<String,Object>b){return s.registerProvider(b);}@GetMapping("/tools")public List<Map<String,String>> tools(){return s.tools();}@PostMapping("/tools")public Map<String,Object> tool(@RequestBody Map<String,Object>b){return s.registerTool(b);}@GetMapping("/prompts")public List<Map<String,Object>> prompts(){return s.prompts();}@PostMapping("/prompts")public Map<String,Object> prompt(@RequestBody Map<String,Object>b){return s.registerPrompt(b);}@GetMapping("/sessions")public List<Map<String,Object>> sessions(){return s.sessions();}@PostMapping("/sessions")public Map<String,Object> session(@RequestParam(required=false)UUID userId,@RequestParam(defaultValue="3600")long ttlSeconds){return s.createSession(userId,Duration.ofSeconds(ttlSeconds));}}
